import React from 'react';

import { IWorkoutFull } from '@apps/Workouts/@types/workouts.types';
import { getDiffDate } from '@helpers/dateHelper';
import { formatDistance } from '@helpers/formatHelper';
import { getDistanceByCoordsInMeters } from '@helpers/gpsHelper';

interface IWorkoutTrackMarkupSelectedProps {
  trackPoints: IWorkoutFull['track'];
}

const WorkoutTrackMarkupSelected: React.FC<IWorkoutTrackMarkupSelectedProps> = ({
  trackPoints,
}) => {
  return (
    <div className="">
      <div className="text-center">
        <small className="text-strong">
          {trackPoints[0].date.toLocaleTimeString()} —{' '}
          {trackPoints[trackPoints.length - 1].date.toLocaleTimeString()}
        </small>
        <br />
        <small>
          <small className="text-info">
            {formatDistance(
              getDistanceByCoordsInMeters(trackPoints.map((x) => x.point) as [number, number][]),
            )}{' '}
            за{' '}
            {getDiffDate(
              trackPoints[0].date,
              trackPoints[trackPoints.length - 1].date,
            ).toLocaleTimeString()}
          </small>
        </small>
      </div>
    </div>
  );
};

export default WorkoutTrackMarkupSelected;
